// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListApiKeys Active API keys
	// (GET /v1/admin/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request)
	// CreateApiKey Create an API key for an integration
	// (POST /v1/admin/api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request)
	// RevokeApiKey Revoke an API key; it stops working at once
	// (DELETE /v1/admin/api-keys/{id})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ListAuditLog Who changed what, newest first
	// (GET /v1/admin/audit-log)
	ListAuditLog(w http.ResponseWriter, r *http.Request, params ListAuditLogParams)
	// AdminListBanners Every banner, hidden ones included
	// (GET /v1/admin/banners)
	AdminListBanners(w http.ResponseWriter, r *http.Request)
	// CreateBanner Add a banner
	// (POST /v1/admin/banners)
	CreateBanner(w http.ResponseWriter, r *http.Request)
	// DeleteBanner Remove a banner
	// (DELETE /v1/admin/banners/{id})
	DeleteBanner(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateBanner Change a banner
	// (PUT /v1/admin/banners/{id})
	UpdateBanner(w http.ResponseWriter, r *http.Request, id Id)
	// CreateCategory Add a category
	// (POST /v1/admin/categories)
	CreateCategory(w http.ResponseWriter, r *http.Request)
	// DeleteCategory Remove a category
	// (DELETE /v1/admin/categories/{id})
	DeleteCategory(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateCategory Rename, move or reorder a category
	// (PUT /v1/admin/categories/{id})
	UpdateCategory(w http.ResponseWriter, r *http.Request, id Id)
	// AdminListDiscounts Every discount code, newest first
	// (GET /v1/admin/discounts)
	AdminListDiscounts(w http.ResponseWriter, r *http.Request)
	// CreateDiscount Add a discount code
	// (POST /v1/admin/discounts)
	CreateDiscount(w http.ResponseWriter, r *http.Request)
	// DeleteDiscount Remove a discount code
	// (DELETE /v1/admin/discounts/{id})
	DeleteDiscount(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateDiscount Change a discount code
	// (PUT /v1/admin/discounts/{id})
	UpdateDiscount(w http.ResponseWriter, r *http.Request, id Id)
	// AdminOverview The numbers on the dashboard's home page
	// (GET /v1/admin/overview)
	AdminOverview(w http.ResponseWriter, r *http.Request)
	// AdminListProducts Every product, drafts and archived included, newest first
	// (GET /v1/admin/products)
	AdminListProducts(w http.ResponseWriter, r *http.Request, params AdminListProductsParams)
	// CreateProduct Add a product
	// (POST /v1/admin/products)
	CreateProduct(w http.ResponseWriter, r *http.Request)
	// DeleteProduct Remove a product for good
	// (DELETE /v1/admin/products/{id})
	DeleteProduct(w http.ResponseWriter, r *http.Request, id Id)
	// AdminGetProduct One product, whatever its status
	// (GET /v1/admin/products/{id})
	AdminGetProduct(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateProduct Replace a product's details, options, variants and images
	// (PUT /v1/admin/products/{id})
	UpdateProduct(w http.ResponseWriter, r *http.Request, id Id)
	// AdminListShippingZones Every delivery zone, inactive ones included
	// (GET /v1/admin/shipping-zones)
	AdminListShippingZones(w http.ResponseWriter, r *http.Request)
	// CreateShippingZone Add a delivery zone
	// (POST /v1/admin/shipping-zones)
	CreateShippingZone(w http.ResponseWriter, r *http.Request)
	// DeleteShippingZone Remove a delivery zone
	// (DELETE /v1/admin/shipping-zones/{id})
	DeleteShippingZone(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateShippingZone Change a delivery zone
	// (PUT /v1/admin/shipping-zones/{id})
	UpdateShippingZone(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateStore Change the shop's settings
	// (PUT /v1/admin/store)
	UpdateStore(w http.ResponseWriter, r *http.Request)
	// UploadImage Upload a JPEG, PNG or WebP image, up to 10 MB
	// (POST /v1/admin/uploads)
	UploadImage(w http.ResponseWriter, r *http.Request)
	// AdjustStock Add to or take from a variant's stock, saying why
	// (POST /v1/admin/variants/{id}/stock-adjustments)
	AdjustStock(w http.ResponseWriter, r *http.Request, id Id)
	// Login Sign in with email or phone and password
	// (POST /v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End this session
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Refresh Swap a refresh token for a new pair
	// (POST /v1/auth/refresh)
	Refresh(w http.ResponseWriter, r *http.Request)
	// Register Create a customer account and sign in
	// (POST /v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// ListBanners The shop's active banners, in display order
	// (GET /v1/banners)
	ListBanners(w http.ResponseWriter, r *http.Request)
	// ListBrands Brands with products for sale, most products first
	// (GET /v1/brands)
	ListBrands(w http.ResponseWriter, r *http.Request)
	// GetCart The shopper's cart
	// (GET /v1/cart)
	GetCart(w http.ResponseWriter, r *http.Request, params GetCartParams)
	// RemoveCartDiscount Take the discount code off the cart
	// (DELETE /v1/cart/discount)
	RemoveCartDiscount(w http.ResponseWriter, r *http.Request, params RemoveCartDiscountParams)
	// ApplyCartDiscount Use a discount code on the cart
	// (PUT /v1/cart/discount)
	ApplyCartDiscount(w http.ResponseWriter, r *http.Request, params ApplyCartDiscountParams)
	// SetCartItem Set how many of a variant are in the cart
	// (PUT /v1/cart/items/{variant_id})
	SetCartItem(w http.ResponseWriter, r *http.Request, variantId openapi_types.UUID, params SetCartItemParams)
	// MergeCart Move a guest cart into the signed-in customer's cart
	// (POST /v1/cart/merge)
	MergeCart(w http.ResponseWriter, r *http.Request)
	// QuoteCartShipping The delivery charge for this cart to a district
	// (POST /v1/cart/shipping-quote)
	QuoteCartShipping(w http.ResponseWriter, r *http.Request, params QuoteCartShippingParams)
	// ListCategories Every category, in display order
	// (GET /v1/categories)
	ListCategories(w http.ResponseWriter, r *http.Request)
	// ListDistricts Bangladesh's 64 districts, by division
	// (GET /v1/districts)
	ListDistricts(w http.ResponseWriter, r *http.Request)
	// GetHealth Is the API up and can it reach its database
	// (GET /v1/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListProducts Products for sale, filtered and sorted
	// (GET /v1/products)
	ListProducts(w http.ResponseWriter, r *http.Request, params ListProductsParams)
	// ListProductFacets What the current filters could still narrow to, with counts
	// (GET /v1/products/facets)
	ListProductFacets(w http.ResponseWriter, r *http.Request, params ListProductFacetsParams)
	// GetProduct One product for sale, with its variants and images
	// (GET /v1/products/{slug})
	GetProduct(w http.ResponseWriter, r *http.Request, slug string)
	// ListShippingZones Where the shop delivers, and what it charges
	// (GET /v1/shipping/zones)
	ListShippingZones(w http.ResponseWriter, r *http.Request)
	// GetStore The shop's public settings
	// (GET /v1/store)
	GetStore(w http.ResponseWriter, r *http.Request, params GetStoreParams)
}

